namespace SaaSPlatform.Api.Tests.ServiceRequests;

#pragma warning disable CA1822

public sealed class ServiceRequestServiceTests
{
    [Fact] public async Task CategoryCodeIsTenantUniqueAndVersioned() { await using var f=await Fixture.Create(); await f.Category(); await Assert.ThrowsAsync<ConflictException>(()=>f.Service.SaveCategory(f.Principal(f.Requester),null,f.CategoryInput(),default)); }
    [Fact] public async Task CreateUsesCategoryDefaultAndSafeSequence() { await using var f=await Fixture.Create();var c=await f.Category();var x=await f.Service.Create(f.Principal(f.Requester),f.Input(c.Id,false),default);Assert.Matches("^SR-[0-9]{4}-[0-9]{6}$",x.Number);Assert.Equal(ServiceRequestPriority.High,x.Priority);Assert.Equal(ServiceRequestStatus.Draft,x.Status); }
    [Fact] public async Task RequiredAssetAndLocationAreValidated() { await using var f=await Fixture.Create();var c=await f.Category(required:true);await Assert.ThrowsAsync<ValidationException>(()=>f.Service.Create(f.Principal(f.Requester),f.Input(c.Id,false),default)); }
    [Fact] public async Task RequesterOnlyListCannotExposeAnotherUsersRequests() { await using var f=await Fixture.Create();var c=await f.Category();await f.Service.Create(f.Principal(f.Requester),f.Input(c.Id,true),default);var list=await f.Service.List(f.Principal(f.Coordinator),new(null,null,null,null,null,null,true,false,1,25),default);Assert.Empty(list.Items); }
    [Fact] public async Task LifecycleEnforcesTriageBeforeAssignment() { await using var f=await Fixture.Create();var x=await f.Submitted();await Assert.ThrowsAsync<ConflictException>(()=>f.Service.Assign(f.Principal(f.Coordinator),x.Id,new(f.Executor.Id,null,x.Version),default));var triaged=await f.Service.Triage(f.Principal(f.Coordinator),x.Id,new(x.CategoryId,null,null,x.Priority,x.Version),default);Assert.Equal(ServiceRequestStatus.UnderReview,triaged.Status);Assert.NotNull(triaged.FirstResponseAtUtc); }
    [Fact] public async Task AssignmentRequiresEligibleActiveMember() { await using var f=await Fixture.Create();var x=await f.Triaged();await Assert.ThrowsAsync<ValidationException>(()=>f.Service.Assign(f.Principal(f.Coordinator),x.Id,new(f.Coordinator.Id,null,x.Version),default));var assigned=await f.Service.Assign(f.Principal(f.Coordinator),x.Id,new(f.Executor.Id,"dispatch",x.Version),default);Assert.Equal(ServiceRequestStatus.Assigned,assigned.Status);Assert.Single(assigned.Assignments); }
    [Fact] public async Task AssignedExecutorCanStartAndResolveThenCoordinatorCloses() { await using var f=await Fixture.Create();var x=await f.Assigned();x=await f.Service.Start(f.Principal(f.Executor),x.Id,new(x.Version),default);x=await f.Service.Resolve(f.Principal(f.Executor),x.Id,new("Restored service",x.Version),default);x=await f.Service.Close(f.Principal(f.Coordinator),x.Id,new(x.Version),default);Assert.Equal(ServiceRequestStatus.Closed,x.Status);Assert.Equal("Restored service",x.ResolutionSummary); }
    [Fact] public async Task ConversionRequiresAssetAndCreatesOneLinkedBreakdown() { await using var f=await Fixture.Create();var x=await f.Triaged();await Assert.ThrowsAsync<ValidationException>(()=>f.Service.ConvertToMaintenance(f.Principal(f.Coordinator),x.Id,new(x.Version),default)); }
    [Fact] public async Task StaleVersionIsRejected() { await using var f=await Fixture.Create();var x=await f.Submitted();await Assert.ThrowsAsync<ConflictException>(()=>f.Service.Triage(f.Principal(f.Coordinator),x.Id,new(x.CategoryId,null,null,x.Priority,Guid.NewGuid()),default)); }
    [Fact] public async Task SchemaHasTenantKeysConcurrencyAndLookupIndexes() { await using var f=await Fixture.Create();var request=f.Database.Model.FindEntityType(typeof(ServiceRequest))!;var category=f.Database.Model.FindEntityType(typeof(ServiceRequestCategory))!;Assert.True(request.FindProperty(nameof(ServiceRequest.Version))!.IsConcurrencyToken);Assert.True(category.FindProperty(nameof(ServiceRequestCategory.Version))!.IsConcurrencyToken);Assert.Contains(request.GetIndexes(),x=>x.IsUnique&&x.Properties.Select(p=>p.Name).SequenceEqual([nameof(ServiceRequest.TenantId),nameof(ServiceRequest.Number)])); }

    private sealed class Fixture : IAsyncDisposable
    {
        public PlatformDbContext Database{get;} public ServiceRequestService Service{get;} public Guid TenantId{get;} public Site Site{get;} public Site OtherSite{get;} public PlatformUser Requester{get;} public PlatformUser Coordinator{get;} public PlatformUser Executor{get;}
        private Fixture(PlatformDbContext db,ServiceRequestService service,Guid tenant,Site site,Site other,PlatformUser requester,PlatformUser coordinator,PlatformUser executor){Database=db;Service=service;TenantId=tenant;Site=site;OtherSite=other;Requester=requester;Coordinator=coordinator;Executor=executor;}
        public static async Task<Fixture>Create()
        {
            var tenantId=Guid.NewGuid();var current=new Current(tenantId);var options=new DbContextOptionsBuilder<PlatformDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;var db=new PlatformDbContext(options,current,TimeProvider.System);
            var tenant=new Tenant{Id=tenantId,Name="Tenant",Slug=$"tenant-{tenantId:N}"};
            var site=NewSite(tenantId,"MAIN");var other=NewSite(tenantId,"OTHER");
            var requester=User("requester");var coordinator=User("coordinator");var executor=User("executor");
            var permission=new PermissionDefinition{Id=Guid.NewGuid(),Code=TenantPermissions.ServiceRequestsExecute,Module="Service Requests",Description="Execute"};var role=new TenantRole{Id=Guid.NewGuid(),TenantId=tenantId,Name="Executor",IsActive=true};role.Permissions.Add(new RolePermissionGrant{TenantId=tenantId,RoleId=role.Id,PermissionId=permission.Id,Role=role,Permission=permission});var membership=new TenantMembership{Id=Guid.NewGuid(),TenantId=tenantId,Tenant=tenant,UserId=executor.Id,User=executor};membership.Roles.Add(new MembershipRole{Id=Guid.NewGuid(),TenantId=tenantId,MembershipId=membership.Id,RoleId=role.Id,Membership=membership,Role=role,ScopeKind=AccessScopeKind.Tenant});db.AddRange(tenant,site,other,requester,coordinator,executor,permission,role,membership,new TenantMembership{Id=Guid.NewGuid(),TenantId=tenantId,Tenant=tenant,UserId=requester.Id,User=requester},new TenantMembership{Id=Guid.NewGuid(),TenantId=tenantId,Tenant=tenant,UserId=coordinator.Id,User=coordinator});await db.SaveChangesAsync();var service=new ServiceRequestService(db,current,new SiteScopeAuthorizer(),new NoAudit(),new FakeMaintenance(db,tenantId),TimeProvider.System);return new(db,service,tenantId,site,other,requester,coordinator,executor);
        }
        public ClaimsPrincipal Principal(PlatformUser user){var claims=new List<Claim>{new("sub",user.Id.ToString())};foreach(var p in TenantPermissions.All){claims.Add(new(TenantClaims.Permission,p));claims.Add(new(TenantClaims.Grant,new PermissionGrant(p,AccessScopeKind.Tenant,null).ToClaimValue()));}return new(new ClaimsIdentity(claims,"test"));}
        public ServiceRequestCategoryInput CategoryInput()=>new("GENERAL","General",null,null,null,ServiceRequestPriority.High,false,false,true,0,null);
        public Task<ServiceRequestCategory> Category(bool required=false){var input=CategoryInput() with{AssetRequired=required,LocationRequired=required};return Service.SaveCategory(Principal(Coordinator),null,input,default);}
        public ServiceRequestInput Input(Guid category,bool submit)=>new(Site.Id,null,category,null,"Water leak","Water is leaking from the ceiling",null,null,submit);
        public async Task<ServiceRequest> Submitted(){var c=await Category();return await Service.Create(Principal(Requester),Input(c.Id,true),default);}
        public async Task<ServiceRequest> Triaged(){var x=await Submitted();return await Service.Triage(Principal(Coordinator),x.Id,new(x.CategoryId,null,null,x.Priority,x.Version),default);}
        public async Task<ServiceRequest> Assigned(){var x=await Triaged();return await Service.Assign(Principal(Coordinator),x.Id,new(Executor.Id,null,x.Version),default);}
        private static Site NewSite(Guid tenant,string code)=>new(){Id=Guid.NewGuid(),TenantId=tenant,Code=code,NameEn=code,TimeZone="UTC"};private static PlatformUser User(string name)=>new(){Id=Guid.NewGuid(),UserName=$"{name}@test.local",Email=$"{name}@test.local",DisplayName=name,IsActive=true};
        public async ValueTask DisposeAsync()=>await Database.DisposeAsync();
    }
    private sealed class Current(Guid id):ICurrentTenant{public Guid? Id{get;private set;}=id;public void Initialize(Guid tenantId)=>Id=tenantId;}
    private sealed class NoAudit:IAuditWriter{public void Add(string action,string entityType,Guid entityId,object? changes=null){}}
    private sealed class FakeMaintenance(PlatformDbContext db,Guid tenant):ICorrectiveMaintenanceService
    {
        public async Task<BreakdownReport>CreateBreakdownFromServiceRequest(ClaimsPrincipal user,BreakdownCreateInput input,CancellationToken ct){var x=new BreakdownReport{Id=Guid.NewGuid(),TenantId=tenant,Number="BR-TEST",AssetId=input.AssetId,SiteId=Guid.NewGuid(),ReportedById=Guid.Parse(user.FindFirstValue("sub")!),ReportedAtUtc=DateTimeOffset.UtcNow,Title=input.Title,Description=input.Description,Priority=input.Priority};db.BreakdownReports.Add(x);await db.SaveChangesAsync(ct);return x;}
        public Task<BreakdownReport>CreateBreakdown(ClaimsPrincipal u,BreakdownCreateInput i,CancellationToken c)=>throw new NotSupportedException();public Task<MaintenancePage<BreakdownReport>>ListBreakdowns(ClaimsPrincipal u,BreakdownListQuery i,CancellationToken c)=>throw new NotSupportedException();public Task<BreakdownReport>GetBreakdown(ClaimsPrincipal u,Guid i,CancellationToken c)=>throw new NotSupportedException();public Task<BreakdownReport>ReviewBreakdown(ClaimsPrincipal u,Guid i,BreakdownReviewInput x,CancellationToken c)=>throw new NotSupportedException();public Task<MaintenancePage<CorrectiveWorkOrder>>ListWorkOrders(ClaimsPrincipal u,WorkOrderListQuery i,CancellationToken c)=>throw new NotSupportedException();public Task<CorrectiveWorkOrder>GetWorkOrder(ClaimsPrincipal u,Guid i,CancellationToken c)=>throw new NotSupportedException();public Task<CorrectiveWorkOrder>CreateWorkOrder(ClaimsPrincipal u,WorkOrderCreateInput i,CancellationToken c)=>throw new NotSupportedException();public Task<CorrectiveWorkOrder>Assign(ClaimsPrincipal u,Guid i,WorkOrderAssignmentInput x,CancellationToken c)=>throw new NotSupportedException();public Task<CorrectiveWorkOrder>Start(ClaimsPrincipal u,Guid i,Guid v,CancellationToken c)=>throw new NotSupportedException();public Task<CorrectiveWorkOrder>AddActivity(ClaimsPrincipal u,Guid i,WorkOrderActivityInput x,CancellationToken c)=>throw new NotSupportedException();public Task<CorrectiveWorkOrder>SaveReport(ClaimsPrincipal u,Guid i,MaintenanceReportInput x,CancellationToken c)=>throw new NotSupportedException();public Task<CorrectiveWorkOrder>SubmitReport(ClaimsPrincipal u,Guid i,Guid v,CancellationToken c)=>throw new NotSupportedException();public Task<CorrectiveWorkOrder>Verify(ClaimsPrincipal u,Guid i,WorkOrderVerificationInput x,CancellationToken c)=>throw new NotSupportedException();public Task<CorrectiveWorkOrder>Cancel(ClaimsPrincipal u,Guid i,WorkOrderCancelInput x,CancellationToken c)=>throw new NotSupportedException();public Task<MaintenanceDashboard>Dashboard(ClaimsPrincipal u,CancellationToken c)=>throw new NotSupportedException();public Task<IReadOnlyList<TechnicianOption>>Technicians(ClaimsPrincipal u,Guid i,CancellationToken c)=>throw new NotSupportedException();public Task<IReadOnlyList<MaintenanceAssetOption>>BreakdownAssets(ClaimsPrincipal u,string? s,CancellationToken c)=>throw new NotSupportedException();public Task<IReadOnlyList<CorrectiveWorkOrder>>AssetHistory(ClaimsPrincipal u,Guid i,CancellationToken c)=>throw new NotSupportedException();
    }
}
